use std::num::NonZeroUsize;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

/// Every way `solve` can fail.
#[derive(Debug)]
pub enum SolveError {
    /// Some `fetch` call failed; `id` names one such request.
    Fetch { id: u32 },
    /// The overall deadline elapsed before every fetch completed.
    Deadline,
    /// The surrounding work was cancelled.
    Cancelled,
}

/// The hard cap on simultaneous in-flight `fetch` calls.
const MAX_IN_FLIGHT: usize = 4;

/// Sentinel meaning "no fetch has reported a failure yet".
const NO_FAILURE: u64 = u64::MAX;

/// Sum the values fetched for every id, at most [`MAX_IN_FLIGHT`] at a time,
/// aborting on the first failure, on the deadline, or on cancellation.
pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let tenant = Tenant::new("aggregate").expect("`aggregate` is a valid tenant name");
    let scope = Scope::root(tenant);
    let limit = NonZeroUsize::new(MAX_IN_FLIGHT).expect("`MAX_IN_FLIGHT` is non-zero");

    // Records the id of the first fetch to fail so the located `each` error can
    // be turned back into the exact id that caused it.
    let failed = Arc::new(AtomicU64::new(NO_FAILURE));

    // Bounded, ordered, fail-fast fan-out: at most four bodies run at once, the
    // first error cancels the rest and starts no further item, and dropping the
    // whole future drops every body it owns.
    let work = each(&scope, "fetch", Some(limit), ids, {
        let failed = Arc::clone(&failed);
        move |_step: Scope, id: u32| {
            let fetch = fetch.clone();
            let failed = Arc::clone(&failed);
            async move {
                match fetch.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        failed.store(u64::from(id), Ordering::SeqCst);
                        Err(FlowError::failed(format!("fetch of {id} failed")))
                    }
                }
            }
        }
    });

    // Racing the fan-out against the deadline also guarantees nothing survives
    // a drop: on timeout the body (and every fetch it owns) is dropped.
    match within(&scope, "aggregate", deadline, work).await {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FlowError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(SolveError::Cancelled),
        Err(_) => {
            let id = failed.load(Ordering::SeqCst);
            Err(SolveError::Fetch {
                id: if id == NO_FAILURE { 0 } else { id as u32 },
            })
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let tenant = match Tenant::new("aggregate") {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let limit = NonZeroUsize::new(4).expect("fan-out bound is non-zero");
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failed_in_body = Arc::clone(&failed);

    let fan_out = each(&scope, "fetch", Some(limit), ids, move |_scope, id| {
        let fetch = fetch.clone();
        let failed = Arc::clone(&failed_in_body);
        async move {
            match fetch.fetch(id).await {
                Ok(value) => Ok(value),
                Err(_) => {
                    if let Ok(mut slot) = failed.lock() {
                        if slot.is_none() {
                            *slot = Some(id);
                        }
                    }
                    Err(FlowError::failed("fetch failed"))
                }
            }
        }
    });

    match within(&scope, "aggregate", deadline, fan_out).await {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(err) => {
            if matches!(&err, FlowError::TimedOut { .. }) {
                Err(SolveError::Deadline)
            } else if err.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                let id = failed.lock().ok().and_then(|slot| *slot).unwrap_or(0);
                Err(SolveError::Fetch { id })
            }
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};

use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let scope = Scope::root(Tenant::new("aggregate").map_err(|_| SolveError::Cancelled)?);
    let limit = NonZeroUsize::new(4).expect("four is non-zero");

    // First failing id observed by any body, or `u64::MAX` if none.
    let failed = Arc::new(AtomicU64::new(u64::MAX));

    let body_failed = Arc::clone(&failed);
    let work = each(&scope, "fetch", Some(limit), ids, move |_step, id| {
        let fetch = fetch.clone();
        let failed = Arc::clone(&body_failed);
        async move {
            match fetch.fetch(id).await {
                Ok(value) => Ok::<u64, FlowError>(value),
                Err(_) => {
                    failed.store(id as u64, Ordering::SeqCst);
                    Err(FlowError::failed(String::from("fetch failed")))
                }
            }
        }
    });

    match within(&scope, "deadline", deadline, work).await {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(error) => {
            let failed_id = failed.load(Ordering::SeqCst);
            if failed_id != u64::MAX {
                Err(SolveError::Fetch {
                    id: failed_id as u32,
                })
            } else if error.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::script::{at_most, each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

fn from_flow(error: FlowError) -> PipelineError {
    match error {
        FlowError::Cancelled { .. } => PipelineError::Cancelled,
        _ => PipelineError::Deadline,
    }
}

// A ready-made flow error used only to make the fetch fan-out abandon the
// sibling on the first failing stage; the real cause is reported above it.
fn stage_failure() -> FlowError {
    match at_most(0) {
        Ok(_) => unreachable!("zero is not a valid concurrency bound"),
        Err(error) => error,
    }
}

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let scope = match Tenant::new("pipeline") {
        Ok(tenant) => Scope::root(tenant),
        Err(error) => return Err(from_flow(error)),
    };

    let fetch_a_failed = Arc::new(AtomicBool::new(false));
    let fetch_b_failed = Arc::new(AtomicBool::new(false));
    let fetcher = stage.clone();

    let fetched: Result<Vec<Artifact>, FlowError> = each(
        &scope,
        "fetch",
        Some(NonZeroUsize::new(2).expect("two is non-zero")),
        vec![StageName::FetchA, StageName::FetchB],
        |_scope, name| {
            let stage = fetcher.clone();
            let fetch_a_failed = Arc::clone(&fetch_a_failed);
            let fetch_b_failed = Arc::clone(&fetch_b_failed);
            async move {
                let is_fetch_a = matches!(&name, StageName::FetchA);
                match stage.run(name).await {
                    Ok(artifact) => Ok(artifact),
                    Err(_) => {
                        if is_fetch_a {
                            fetch_a_failed.store(true, Ordering::Relaxed);
                        } else {
                            fetch_b_failed.store(true, Ordering::Relaxed);
                        }
                        Err(stage_failure())
                    }
                }
            }
        },
    )
    .await;

    if let Err(error) = fetched {
        if fetch_a_failed.load(Ordering::Relaxed) {
            return Err(PipelineError::Stage { name: StageName::FetchA });
        }
        if fetch_b_failed.load(Ordering::Relaxed) {
            return Err(PipelineError::Stage { name: StageName::FetchB });
        }
        return Err(from_flow(error));
    }

    if stage.run(StageName::Combine).await.is_err() {
        return Err(PipelineError::Stage { name: StageName::Combine });
    }

    match stage.run(StageName::Publish).await {
        Ok(published) => Ok(Published::from(published)),
        Err(_) => Err(PipelineError::Stage { name: StageName::Publish }),
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let gate = match Tenant::new("pipeline") {
        Ok(tenant) => Scope::root(tenant),
        Err(error) => return Err(from_flow(error)),
    };

    let outcome: Result<Result<Published, PipelineError>, FlowError> = within(
        &gate,
        "solve",
        deadline,
        async move { Ok::<Result<Published, PipelineError>, FlowError>(pipeline(stage).await) },
    )
    .await;

    match outcome {
        Ok(result) => result,
        Err(error) => Err(from_flow(error)),
    }
}

use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::script::{at_most, each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(tenant) => tenant,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let failed: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));

    match within(
        &scope,
        "pipeline",
        deadline,
        run_pipeline(&scope, &stage, &failed),
    )
    .await
    {
        Ok(published) => Ok(published),
        Err(FlowError::TimedOut { .. }) => Err(PipelineError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(PipelineError::Cancelled),
        Err(_) => Err(PipelineError::Stage {
            name: take_failed(&failed),
        }),
    }
}

async fn run_pipeline(
    scope: &Scope,
    stage: &Stage,
    failed: &Arc<Mutex<Option<StageName>>>,
) -> Result<Published, FlowError> {
    let limit = at_most(2)?;
    let fetches = vec![StageName::FetchA, StageName::FetchB];
    let _artifacts: Vec<Artifact> = each(
        scope,
        "fetch",
        Some(limit),
        fetches,
        move |_child: Scope, name: StageName| {
            let stage = Stage::clone(stage);
            let failed = Arc::clone(failed);
            let run_name = StageName::clone(&name);
            async move {
                match stage.run(run_name).await {
                    Ok(artifact) => Ok(artifact),
                    Err(_) => {
                        record(&failed, name);
                        Err(FlowError::failed("fetch stage failed"))
                    }
                }
            }
        },
    )
    .await?;

    let _combined = match stage.run(StageName::Combine).await {
        Ok(artifact) => artifact,
        Err(_) => {
            record(failed, StageName::Combine);
            return Err(FlowError::failed("combine stage failed"));
        }
    };

    let published = match stage.run(StageName::Publish).await {
        Ok(artifact) => artifact,
        Err(_) => {
            record(failed, StageName::Publish);
            return Err(FlowError::failed("publish stage failed"));
        }
    };

    Ok(Published::from(published))
}

fn record(failed: &Arc<Mutex<Option<StageName>>>, name: StageName) {
    if let Ok(mut slot) = failed.lock() {
        if slot.is_none() {
            *slot = Some(name);
        }
    }
}

fn take_failed(failed: &Arc<Mutex<Option<StageName>>>) -> StageName {
    match failed.lock() {
        Ok(mut slot) => slot.take().unwrap_or(StageName::FetchA),
        Err(_) => StageName::FetchA,
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::task::{Context, Poll};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let at = Instant::now() + deadline;
    match Timeout::new(run_pipeline(&stage), at).await {
        Some(result) => result,
        None => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: &Stage) -> Result<Published, PipelineError> {
    let fetched = FetchJoin {
        a: Some(Box::pin(stage.run(StageName::FetchA))),
        b: Some(Box::pin(stage.run(StageName::FetchB))),
        ra: None,
        rb: None,
    }
    .await;

    let (_a, _b) = fetched.map_err(|name| PipelineError::Stage { name })?;

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

struct FetchJoin<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    ra: Option<Artifact>,
    rb: Option<Artifact>,
}

impl<A, B> Future for FetchJoin<A, B>
where
    A: Future<Output = Result<Artifact, StageError>>,
    B: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(Artifact, Artifact), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.ra.is_none() {
            if let Some(fut) = this.a.as_mut() {
                match fut.as_mut().poll(cx) {
                    Poll::Ready(Ok(value)) => {
                        this.ra = Some(value);
                        this.a = None;
                    }
                    Poll::Ready(Err(_)) => {
                        return Poll::Ready(Err(StageName::FetchA));
                    }
                    Poll::Pending => {}
                }
            }
        }

        if this.rb.is_none() {
            if let Some(fut) = this.b.as_mut() {
                match fut.as_mut().poll(cx) {
                    Poll::Ready(Ok(value)) => {
                        this.rb = Some(value);
                        this.b = None;
                    }
                    Poll::Ready(Err(_)) => {
                        return Poll::Ready(Err(StageName::FetchB));
                    }
                    Poll::Pending => {}
                }
            }
        }

        match (this.ra.take(), this.rb.take()) {
            (Some(a), Some(b)) => Poll::Ready(Ok((a, b))),
            (a, b) => {
                this.ra = a;
                this.rb = b;
                Poll::Pending
            }
        }
    }
}

struct Timeout<F> {
    inner: F,
    at: Instant,
    armed: bool,
    finished: Arc<AtomicBool>,
}

impl<F> Timeout<F> {
    fn new(inner: F, at: Instant) -> Self {
        Self {
            inner,
            at,
            armed: false,
            finished: Arc::new(AtomicBool::new(false)),
        }
    }
}

impl<F: Future> Future for Timeout<F> {
    type Output = Option<F::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };

        let inner = unsafe { Pin::new_unchecked(&mut this.inner) };
        if let Poll::Ready(output) = inner.poll(cx) {
            this.finished.store(true, Ordering::SeqCst);
            return Poll::Ready(Some(output));
        }

        if Instant::now() >= this.at {
            this.finished.store(true, Ordering::SeqCst);
            return Poll::Ready(None);
        }

        if !this.armed {
            this.armed = true;
            let waker = cx.waker().clone();
            let at = this.at;
            let finished = Arc::clone(&this.finished);
            let _ = thread::Builder::new()
                .name("pipeline-deadline".to_string())
                .spawn(move || {
                    loop {
                        let now = Instant::now();
                        if now >= at {
                            break;
                        }
                        thread::sleep(at - now);
                    }
                    if !finished.load(Ordering::SeqCst) {
                        waker.wake();
                    }
                });
        }

        Poll::Pending
    }
}

impl<F> Drop for Timeout<F> {
    fn drop(&mut self) {
        self.finished.store(true, Ordering::SeqCst);
    }
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let work = async {
        let mut sum: u64 = 0;

        for chunk in ids.chunks(4) {
            let futures = chunk.iter().map(|&id| {
                let fetcher = fetch.clone();
                async move {
                    match fetcher.fetch(id).await {
                        Ok(value) => Ok((id, value)),
                        Err(_) => Err(id),
                    }
                }
            });

            let results = join_all_bounded(4, futures).await;

            for result in results {
                match result {
                    Ok((_, value)) => sum += value,
                    Err(id) => return Err(SolveError::Fetch { id }),
                }
            }
        }

        Ok(sum)
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut tasks: JoinSet<Result<(u32, u64), u32>> = JoinSet::new();
    let mut pending = ids.into_iter();
    let mut sum: u64 = 0;

    for _ in 0..MAX_IN_FLIGHT {
        match pending.next() {
            Some(id) => spawn_fetch(&mut tasks, &fetch, id),
            None => break,
        }
    }

    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok((_, value))) => {
                sum += value;
                if let Some(next) = pending.next() {
                    spawn_fetch(&mut tasks, &fetch, next);
                }
            }
            Ok(Err(id)) => {
                tasks.abort_all();
                while tasks.join_next().await.is_some() {}
                return Err(SolveError::Fetch { id });
            }
            Err(_) => {
                tasks.abort_all();
                while tasks.join_next().await.is_some() {}
                return Err(SolveError::Cancelled);
            }
        }
    }

    Ok(sum)
}

fn spawn_fetch(tasks: &mut JoinSet<Result<(u32, u64), u32>>, fetch: &Fetcher, id: u32) {
    let fetch = fetch.clone();
    tasks.spawn(async move {
        match fetch.fetch(id).await {
            Ok(value) => Ok((id, value)),
            Err(_) => Err(id),
        }
    });
}

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::{timeout, Instant};

/// Upper bound on the number of `fetch` calls allowed to run concurrently.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// Spawn a single fetch onto `set`, tagging the result with its id on failure.
fn spawn_fetch(set: &mut JoinSet<Result<u64, u32>>, fetch: &ai_task_support::Fetcher, id: u32) {
    let fetcher = fetch.clone();
    let _ = set.spawn(async move {
        match fetcher.fetch(id).await {
            Ok(value) => Ok(value),
            Err(_) => Err(id),
        }
    });
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let start = Instant::now();
    let total = ids.len();

    let mut set: JoinSet<Result<u64, u32>> = JoinSet::new();
    let mut next = 0usize;
    let mut in_flight = 0usize;
    let mut sum = 0u64;

    // Prime the pump with up to MAX_IN_FLIGHT tasks.
    while in_flight < MAX_IN_FLIGHT && next < total {
        if start.elapsed() >= deadline {
            set.abort_all();
            return Err(SolveError::Deadline);
        }
        spawn_fetch(&mut set, &fetch, ids[next]);
        next += 1;
        in_flight += 1;
    }

    while in_flight > 0 {
        let remaining = deadline.saturating_sub(start.elapsed());
        let result = match timeout(remaining, set.join_next()).await {
            Ok(Some(result)) => result,
            Ok(None) => break,
            Err(_) => {
                set.abort_all();
                return Err(SolveError::Deadline);
            }
        };

        in_flight -= 1;
        match result {
            Ok(Ok(value)) => sum += value,
            Ok(Err(id)) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Err(_) => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }

        // Absorb every already-finished task before admitting new work, so no
        // fetch begins once a failure has been observed.
        while let Some(result) = set.try_join_next() {
            in_flight -= 1;
            match result {
                Ok(Ok(value)) => sum += value,
                Ok(Err(id)) => {
                    set.abort_all();
                    return Err(SolveError::Fetch { id });
                }
                Err(_) => {
                    set.abort_all();
                    return Err(SolveError::Cancelled);
                }
            }
        }

        // Refill freed slots, but never start a fetch at or past the deadline.
        while in_flight < MAX_IN_FLIGHT && next < total {
            if start.elapsed() >= deadline {
                set.abort_all();
                return Err(SolveError::Deadline);
            }
            spawn_fetch(&mut set, &fetch, ids[next]);
            next += 1;
            in_flight += 1;
        }
    }

    Ok(sum)
}

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct FetchJoin<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    a_ok: Option<Box<Artifact>>,
    b_ok: Option<Box<Artifact>>,
}

impl<A, B> Future for FetchJoin<A, B>
where
    A: Future<Output = Result<Artifact, StageError>>,
    B: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(Artifact, Artifact), usize>;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.as_mut().get_mut();

        let mut finished_a: Option<Result<Artifact, ()>> = None;
        if let Some(fut) = this.a.as_mut() {
            if let Poll::Ready(result) = fut.as_mut().poll(cx) {
                finished_a = Some(result.map_err(|_| ()));
            }
        }
        if let Some(result) = finished_a {
            this.a = None;
            match result {
                Ok(artifact) => this.a_ok = Some(Box::new(artifact)),
                Err(()) => return Poll::Ready(Err(0)),
            }
        }

        let mut finished_b: Option<Result<Artifact, ()>> = None;
        if let Some(fut) = this.b.as_mut() {
            if let Poll::Ready(result) = fut.as_mut().poll(cx) {
                finished_b = Some(result.map_err(|_| ()));
            }
        }
        if let Some(result) = finished_b {
            this.b = None;
            match result {
                Ok(artifact) => this.b_ok = Some(Box::new(artifact)),
                Err(()) => return Poll::Ready(Err(1)),
            }
        }

        match (this.a_ok.take(), this.b_ok.take()) {
            (Some(a), Some(b)) => Poll::Ready(Ok((*a, *b))),
            (a, b) => {
                this.a_ok = a;
                this.b_ok = b;
                Poll::Pending
            }
        }
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let fetches = FetchJoin {
            a: Some(Box::pin(stage.run(StageName::FetchA))),
            b: Some(Box::pin(stage.run(StageName::FetchB))),
            a_ok: None,
            b_ok: None,
        };

        match fetches.await {
            Ok((_a, _b)) => {}
            Err(0) => return Err(PipelineError::Stage { name: StageName::FetchA }),
            Err(_) => return Err(PipelineError::Stage { name: StageName::FetchB }),
        }

        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

        let published: Published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })?
            .into();

        Ok(published)
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, drive(&stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn drive(stage: &Stage) -> Result<Published, PipelineError> {
    let mut tasks: JoinSet<Result<(), PipelineError>> = JoinSet::new();

    {
        let owned: Stage = stage.clone();
        tasks.spawn(async move {
            owned
                .run(StageName::FetchA)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchA,
                })?;
            Ok(())
        });
    }

    {
        let owned: Stage = stage.clone();
        tasks.spawn(async move {
            owned
                .run(StageName::FetchB)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchB,
                })?;
            Ok(())
        });
    }

    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok(())) => {}
            Ok(Err(failure)) => {
                tasks.abort_all();
                return Err(failure);
            }
            Err(_) => {
                tasks.abort_all();
                return Err(PipelineError::Stage {
                    name: StageName::FetchA,
                });
            }
        }
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact: Artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

use std::future::Future;
use std::pin::pin;
use std::task::Poll;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    fetch_both(stage.run(StageName::FetchA), stage.run(StageName::FetchB))
        .await
        .map_err(|name| PipelineError::Stage { name })?;

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

async fn fetch_both<A, B>(a_fut: A, b_fut: B) -> Result<(Artifact, Artifact), StageName>
where
    A: Future<Output = Result<Artifact, StageError>>,
    B: Future<Output = Result<Artifact, StageError>>,
{
    let mut a_fut = pin!(a_fut);
    let mut b_fut = pin!(b_fut);
    let mut a_out: Option<Result<Artifact, StageError>> = None;
    let mut b_out: Option<Result<Artifact, StageError>> = None;

    std::future::poll_fn(move |cx| {
        if a_out.is_none() {
            if let Poll::Ready(res) = a_fut.as_mut().poll(cx) {
                a_out = Some(res);
            }
        }
        if b_out.is_none() {
            if let Poll::Ready(res) = b_fut.as_mut().poll(cx) {
                b_out = Some(res);
            }
        }

        if matches!(a_out.as_ref(), Some(Err(_))) {
            return Poll::Ready(Err(StageName::FetchA));
        }
        if matches!(b_out.as_ref(), Some(Err(_))) {
            return Poll::Ready(Err(StageName::FetchB));
        }

        if a_out.is_some() && b_out.is_some() {
            match (a_out.take(), b_out.take()) {
                (Some(Ok(a)), Some(Ok(b))) => return Poll::Ready(Ok((a, b))),
                _ => {}
            }
        }

        Poll::Pending
    })
    .await
}

use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Solver::new(ids, fetch, deadline).await
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

struct Signal {
    outer: Mutex<Option<Waker>>,
}

impl Signal {
    fn set_outer(&self, waker: &Waker) {
        let mut outer = lock(&self.outer);
        let stale = match outer.as_ref() {
            Some(current) => !current.will_wake(waker),
            None => true,
        };
        if stale {
            *outer = Some(waker.clone());
        }
    }

    fn wake_outer(&self) {
        let waker = lock(&self.outer).clone();
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn clear_outer(&self) {
        *lock(&self.outer) = None;
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        self.wake_outer();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.wake_outer();
    }
}

struct FetchSlot(Fetcher);

impl Unpin for FetchSlot {}

struct Call(Option<Pin<Box<dyn Future<Output = Result<u64, FetchError>>>>>);

// SAFETY: a call is created and polled only by the solver, from the single
// thread that drives it, and is dropped there; the waker it is handed only
// reaches `Signal`, never the call itself.
unsafe impl Send for Call {}

struct InFlight {
    id: u32,
    call: Call,
}

impl Call {
    fn poll_once(&mut self, waker: &Waker) -> Option<Result<u64, FetchError>> {
        let mut cx = Context::from_waker(waker);
        let polled = match self.0.as_mut() {
            Some(call) => call.as_mut().poll(&mut cx),
            None => return None,
        };
        match polled {
            Poll::Pending => None,
            Poll::Ready(outcome) => {
                self.0 = None;
                Some(outcome)
            }
        }
    }
}

struct Solver {
    signal: Arc<Signal>,
    waker: Waker,
    fetch: FetchSlot,
    ids: VecDeque<u32>,
    deadline: Option<Instant>,
    in_flight: Vec<InFlight>,
    sum: u64,
    error: Option<SolveError>,
    stop: Arc<AtomicBool>,
    timer: Option<JoinHandle<()>>,
}

impl Solver {
    fn new(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Self {
        let deadline = Instant::now().checked_add(deadline);
        let signal = Arc::new(Signal {
            outer: Mutex::new(None),
        });
        let waker = Waker::from(Arc::clone(&signal));
        let stop = Arc::new(AtomicBool::new(false));
        let timer = match deadline {
            Some(at) => {
                let flag = Arc::clone(&stop);
                let wake = waker.clone();
                thread::Builder::new()
                    .name(String::from("aggregate-deadline"))
                    .spawn(move || {
                        loop {
                            if flag.load(Ordering::SeqCst) {
                                return;
                            }
                            match at.checked_duration_since(Instant::now()) {
                                Some(left) => thread::park_timeout(left),
                                None => break,
                            }
                        }
                        if !flag.load(Ordering::SeqCst) {
                            wake.wake_by_ref();
                        }
                    })
                    .ok()
            }
            None => None,
        };
        Solver {
            signal,
            waker,
            fetch: FetchSlot(fetch),
            ids: ids.into(),
            deadline,
            in_flight: Vec::new(),
            sum: 0,
            error: None,
            stop,
            timer,
        }
    }

    fn expired(&self) -> bool {
        match self.deadline {
            Some(at) => Instant::now() >= at,
            None => false,
        }
    }

    fn step(&mut self) -> bool {
        let mut progress = false;
        loop {
            let mut pending = Vec::with_capacity(MAX_IN_FLIGHT);
            let mut failed = None;
            for mut call in std::mem::take(&mut self.in_flight) {
                match call.call.poll_once(&self.waker) {
                    Some(Ok(value)) => {
                        self.sum = self.sum.wrapping_add(value);
                        progress = true;
                    }
                    Some(Err(_)) => {
                        failed = Some(call.id);
                        progress = true;
                        break;
                    }
                    None => pending.push(call),
                }
            }
            self.in_flight = pending;

            if let Some(id) = failed {
                self.error = Some(SolveError::Fetch { id });
                return true;
            }

            if (!self.ids.is_empty() || !self.in_flight.is_empty()) && self.expired() {
                self.error = Some(SolveError::Deadline);
                return true;
            }

            let mut started = false;
            while self.in_flight.len() < MAX_IN_FLIGHT {
                let Some(id) = self.ids.pop_front() else {
                    break;
                };
                let fetch = self.fetch.0.clone();
                let call: Pin<Box<dyn Future<Output = Result<u64, FetchError>>>> =
                    Box::pin(async move { fetch.fetch(id).await });
                self.in_flight.push(InFlight { id, call: Call(Some(call)) });
                started = true;
                progress = true;
            }

            if !started {
                return progress;
            }
        }
    }

    fn settle(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        if let Some(timer) = &self.timer {
            timer.thread().unpark();
        }
        self.signal.clear_outer();
        self.in_flight.clear();
    }
}

impl Future for Solver {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();
        me.signal.set_outer(cx.waker());
        loop {
            let progress = me.step();
            if let Some(err) = me.error.take() {
                me.settle();
                return Poll::Ready(Err(err));
            }
            if me.ids.is_empty() && me.in_flight.is_empty() {
                let sum = me.sum;
                me.settle();
                return Poll::Ready(Ok(sum));
            }
            if !progress {
                return Poll::Pending;
            }
        }
    }
}

impl Drop for Solver {
    fn drop(&mut self) {
        self.settle();
    }
}

//! Bounded concurrent aggregation of fetched values.
//!
//! `solve` drives at most `MAX_IN_FLIGHT` fetches at a time, sums their values,
//! and fails fast: the first observed fetch error or an expired deadline stops
//! the fan-out and drops every future still in flight.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::task::{Context, Poll};
use std::thread;
use std::time::{Duration, Instant};

/// Upper bound on simultaneously running fetches.
const MAX_IN_FLIGHT: usize = 4;

/// Longest single sleep a deadline timer thread performs before re-checking
/// the stop flag, so a finished `solve` never leaves a sleeper behind for long.
const POLL_SLICE: Duration = Duration::from_millis(20);

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

impl std::fmt::Display for SolveError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SolveError::Fetch { id } => write!(f, "fetch {id} failed"),
            SolveError::Deadline => write!(f, "deadline exceeded"),
            SolveError::Cancelled => write!(f, "cancelled"),
        }
    }
}

impl std::error::Error for SolveError {}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let total = ids.len();
    let watchdog = Watchdog::new();
    let mut timer = DeadlineTimer::new(deadline, Arc::clone(&watchdog.stop));
    let mut slots: Vec<Option<InFlight<'_>>> = Vec::with_capacity(MAX_IN_FLIGHT);
    let mut next = 0usize;
    let mut collected = 0usize;
    let mut sum = 0u64;

    let outcome = poll_fn(|cx| {
        // Deadline first: never start a fetch once the deadline has passed.
        if Pin::new(&mut timer).poll(cx).is_ready() {
            return Poll::Ready(Err(SolveError::Deadline));
        }

        while slots.len() < MAX_IN_FLIGHT && next < total {
            let id = ids[next];
            next += 1;
            slots.push(Some(InFlight {
                id,
                fut: Box::pin(fetch.fetch(id)),
            }));
        }

        for index in 0..slots.len() {
            let event = match slots[index].as_mut() {
                None => None,
                Some(entry) => Some((entry.id, entry.fut.as_mut().poll(cx))),
            };
            match event {
                Some((_, Poll::Ready(Ok(value)))) => {
                    slots[index] = None;
                    collected += 1;
                    sum = sum.wrapping_add(value);
                }
                Some((id, Poll::Ready(Err(_)))) => {
                    slots[index] = None;
                    return Poll::Ready(Err(SolveError::Fetch { id }));
                }
                _ => {}
            }
        }

        if collected == total {
            Poll::Ready(Ok(sum))
        } else {
            Poll::Pending
        }
    })
    .await;

    // Drop every fetch still in flight; nothing outlives this call.
    drop(slots);
    drop(watchdog);
    outcome
}

/// One running fetch, kept alive only for as long as `solve` lives.
struct InFlight<'a> {
    id: u32,
    fut: Pin<Box<dyn Future<Output = Result<u64, ai_task_support::FetchError>> + 'a>>,
}

/// Tells the deadline timer thread that nobody is waiting for it any more.
struct Watchdog {
    stop: Arc<AtomicBool>,
}

impl Watchdog {
    fn new() -> Self {
        Watchdog {
            stop: Arc::new(AtomicBool::new(false)),
        }
    }
}

impl Drop for Watchdog {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Relaxed);
    }
}

/// A one-shot deadline future backed by a sleeping thread.
///
/// `at` is `None` when the requested duration cannot be represented, which is
/// treated as "no deadline" rather than as an immediate expiry.
struct DeadlineTimer {
    at: Option<Instant>,
    stop: Arc<AtomicBool>,
    armed: bool,
    spin: bool,
}

impl DeadlineTimer {
    fn new(after: Duration, stop: Arc<AtomicBool>) -> Self {
        DeadlineTimer {
            at: Instant::now().checked_add(after),
            stop,
            armed: false,
            spin: false,
        }
    }
}

impl Future for DeadlineTimer {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        let at = match this.at {
            Some(at) => at,
            None => return Poll::Pending,
        };
        let now = Instant::now();
        if now >= at {
            return Poll::Ready(());
        }

        if !this.armed {
            this.armed = true;
            let stop = Arc::clone(&this.stop);
            let waker = cx.waker().clone();
            let spawned = thread::Builder::new().spawn(move || {
                while !stop.load(Ordering::Relaxed) {
                    let now = Instant::now();
                    if now >= at {
                        break;
                    }
                    thread::sleep((at - now).min(POLL_SLICE));
                }
                waker.wake();
            });
            this.spin = spawned.is_err();
        }

        if this.spin {
            // No timer thread available: nudge the task to re-poll shortly.
            thread::sleep((at - now).min(POLL_SLICE));
            cx.waker().wake_by_ref();
        }

        Poll::Pending
    }
}

//! Bounded, fail-fast aggregation of `Fetcher` results.

use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

/// The hard ceiling on fetch calls that may be in flight at once.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchFuture = Pin<Box<dyn Future<Output = Result<u64, FetchError>> + Send + 'static>>;

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Wake plumbing: a fetch that completes, or the deadline timer, must both
/// release a park and re-schedule the task that is polling us.
struct Signal {
    owner: thread::Thread,
    caller: Mutex<Option<Waker>>,
}

impl Signal {
    fn new() -> Arc<Signal> {
        Arc::new(Signal {
            owner: thread::current(),
            caller: Mutex::new(None),
        })
    }

    /// Remember the waker of the task polling us. Called only after the last
    /// poll of the in-flight fetches, so a wake can never be lost.
    fn register(&self, waker: &Waker) {
        let mut slot = lock(&self.caller);
        let already = matches!(slot.as_ref(), Some(existing) if existing.will_wake(waker));
        if !already {
            *slot = Some(waker.clone());
        }
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        Wake::wake_by_ref(&self);
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.owner.unpark();
        let waker = lock(&self.caller).take();
        if let Some(waker) = waker {
            waker.wake();
        }
    }
}

struct TimerCtl {
    done: Mutex<bool>,
    changed: Condvar,
    signal: Arc<Signal>,
    deadline: Instant,
}

impl TimerCtl {
    fn wait(self: Arc<TimerCtl>) {
        let mut done = lock(&self.done);
        loop {
            if *done {
                return;
            }
            let now = Instant::now();
            if now >= self.deadline {
                break;
            }
            let (guard, _) = self
                .changed
                .wait_timeout(done, self.deadline - now)
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            done = guard;
        }
        drop(done);
        Wake::wake_by_ref(&self.signal);
    }
}

/// Stopping the timer when the run finishes keeps one short-lived thread per
/// `solve` instead of one that lingers for the whole deadline.
struct DeadlineTimer {
    ctl: Arc<TimerCtl>,
}

impl Drop for DeadlineTimer {
    fn drop(&mut self) {
        let mut done = lock(&self.ctl.done);
        *done = true;
        self.ctl.changed.notify_all();
    }
}

/// The whole of the run, owned by the future handed back to the caller:
/// dropping that future drops every fetch that is still in flight.
struct Drive {
    fetch: Box<Fetcher>,
    queue: VecDeque<u32>,
    active: Vec<(u32, FetchFuture)>,
    sum: u64,
    failed: Option<u32>,
    deadline: Instant,
    signal: Arc<Signal>,
    timer: Option<DeadlineTimer>,
    no_yield: bool,
}

impl Drive {
    fn new(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Drive {
        Drive {
            fetch: Box::new(fetch),
            queue: ids.into(),
            active: Vec::new(),
            sum: 0,
            failed: None,
            deadline: Instant::now() + deadline,
            signal: Signal::new(),
            timer: None,
            no_yield: false,
        }
    }

    fn arm_timer(&mut self) {
        let ctl = Arc::new(TimerCtl {
            done: Mutex::new(false),
            changed: Condvar::new(),
            signal: self.signal.clone(),
            deadline: self.deadline,
        });
        self.timer = Some(DeadlineTimer { ctl: ctl.clone() });
        let spawned = thread::Builder::new()
            .name("aggregate-deadline".to_string())
            .spawn(move || ctl.wait())
            .is_ok();
        if !spawned {
            // Without the timer we must not hand control back, so stay in the
            // poll and watch the clock ourselves.
            self.timer = None;
            self.no_yield = true;
        }
    }

    fn step(&mut self, cx: &mut Context<'_>) -> Poll<Result<u64, SolveError>> {
        loop {
            if let Some(id) = self.failed {
                return Poll::Ready(Err(SolveError::Fetch { id }));
            }
            if self.queue.is_empty() && self.active.is_empty() {
                return Poll::Ready(Ok(self.sum));
            }
            if Instant::now() >= self.deadline {
                self.active.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }
            if self.timer.is_none() && !self.no_yield {
                self.arm_timer();
            }

            // Nothing new starts once a failure has been seen: the check at the
            // top of the loop runs before this refill.
            while self.active.len() < MAX_IN_FLIGHT {
                let id = match self.queue.pop_front() {
                    Some(id) => id,
                    None => break,
                };
                let fetcher = (*self.fetch).clone();
                self.active
                    .push((id, Box::pin(async move { fetcher.fetch(id).await })));
            }

            let waker = Waker::from(self.signal.clone());
            let mut inner = Context::from_waker(&waker);
            let mut pending: Vec<(u32, FetchFuture)> = Vec::with_capacity(MAX_IN_FLIGHT);
            for (id, mut fut) in std::mem::take(&mut self.active) {
                match fut.as_mut().poll(&mut inner) {
                    Poll::Ready(Ok(value)) => self.sum = self.sum.saturating_add(value),
                    Poll::Ready(Err(_)) => {
                        if self.failed.is_none() {
                            self.failed = Some(id);
                        }
                    }
                    Poll::Pending => pending.push((id, fut)),
                }
            }
            self.active = pending;

            if self.active.is_empty() || self.failed.is_some() {
                continue;
            }

            self.signal.register(cx.waker());
            if self.no_yield {
                thread::park_timeout(Duration::from_millis(1));
                continue;
            }
            return Poll::Pending;
        }
    }
}

impl Future for Drive {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        self.get_mut().step(cx)
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Drive::new(ids, fetch, deadline).await
}

use std::future::{poll_fn, Future};
use std::io;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// What a single stage hands back to `solve`: the artifact it produced, or a
/// marker that it failed. The stage error itself is only ever observed on the
/// worker thread that polled it, so it never has to cross a thread boundary.
type Outcome = Result<Artifact, ()>;

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

// ---------------------------------------------------------------------------
// One-shot value handoff
// ---------------------------------------------------------------------------

struct SlotInner<T> {
    value: Option<T>,
    waker: Option<Waker>,
}

struct Slot<T> {
    inner: Mutex<SlotInner<T>>,
}

impl<T> Slot<T> {
    fn new() -> Self {
        Slot {
            inner: Mutex::new(SlotInner {
                value: None,
                waker: None,
            }),
        }
    }

    fn set(&self, value: T) {
        let waker = {
            let mut g = lock(&self.inner);
            g.value = Some(value);
            g.waker.take()
        };
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn take_ready(&self, cx: &mut Context<'_>) -> Poll<T> {
        let mut g = lock(&self.inner);
        match g.value.take() {
            Some(value) => Poll::Ready(value),
            None => {
                g.waker = Some(cx.waker().clone());
                Poll::Pending
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Cancellation
// ---------------------------------------------------------------------------

#[derive(Clone, Default)]
struct Cancel {
    flag: Arc<AtomicBool>,
}

impl Cancel {
    fn is_set(&self) -> bool {
        self.flag.load(Ordering::SeqCst)
    }

    fn set(&self) {
        self.flag.store(true, Ordering::SeqCst);
    }
}

// ---------------------------------------------------------------------------
// Deadline timer
// ---------------------------------------------------------------------------

struct TimerInner {
    waker: Option<Waker>,
    fired: bool,
    cancelled: bool,
}

struct Timer {
    inner: Mutex<TimerInner>,
    signal: Condvar,
}

impl Timer {
    fn new() -> Self {
        Timer {
            inner: Mutex::new(TimerInner {
                waker: None,
                fired: false,
                cancelled: false,
            }),
            signal: Condvar::new(),
        }
    }

    fn run(&self, at: Instant) {
        let mut g = lock(&self.inner);
        loop {
            if g.cancelled || g.fired {
                return;
            }
            let now = Instant::now();
            if now >= at {
                g.fired = true;
                let waker = g.waker.take();
                drop(g);
                if let Some(waker) = waker {
                    waker.wake();
                }
                return;
            }
            g = match self.signal.wait_timeout(g, at - now) {
                Ok((guard, _)) => guard,
                Err(poisoned) => poisoned.into_inner().0,
            };
        }
    }

    fn arm(&self, waker: &Waker) {
        let mut g = lock(&self.inner);
        if g.cancelled || g.fired {
            drop(g);
            waker.wake_by_ref();
            return;
        }
        g.waker = Some(waker.clone());
    }

    fn cancel(&self) {
        let mut g = lock(&self.inner);
        g.cancelled = true;
        drop(g);
        self.signal.notify_all();
    }
}

// ---------------------------------------------------------------------------
// Ownership of every thread `solve` starts
// ---------------------------------------------------------------------------

struct Abort {
    cancel: Cancel,
    threads: Mutex<Vec<JoinHandle<()>>>,
    timers: Mutex<Vec<Arc<Timer>>>,
}

impl Abort {
    fn new() -> Self {
        Abort {
            cancel: Cancel::default(),
            threads: Mutex::new(Vec::new()),
            timers: Mutex::new(Vec::new()),
        }
    }

    fn track(&self, handle: io::Result<JoinHandle<()>>) {
        if let Ok(handle) = handle {
            lock(&self.threads).push(handle);
        }
    }

    fn spawn_stage(&self, stage: Arc<Stage>, name: StageName) -> Arc<Slot<Outcome>> {
        let slot = Arc::new(Slot::new());
        let worker_slot = Arc::clone(&slot);
        let cancel = self.cancel.clone();
        self.track(thread::Builder::new().spawn(move || {
            drive_stage(stage, name, cancel, worker_slot)
        }));
        slot
    }

    fn timer(&self, at: Instant) -> Arc<Timer> {
        let timer = Arc::new(Timer::new());
        let worker = Arc::clone(&timer);
        self.track(thread::Builder::new().spawn(move || worker.run(at)));
        lock(&self.timers).push(Arc::clone(&timer));
        timer
    }
}

impl Drop for Abort {
    fn drop(&mut self) {
        self.cancel.set();
        for timer in lock(&self.timers).iter() {
            timer.cancel();
        }
        let handles = std::mem::take(&mut *lock(&self.threads));
        for handle in &handles {
            handle.thread().unpark();
        }
        for handle in handles {
            let _ = handle.join();
        }
    }
}

// ---------------------------------------------------------------------------
// Stage driver
// ---------------------------------------------------------------------------

struct ThreadWaker(thread::Thread);

impl Wake for ThreadWaker {
    fn wake(self: Arc<Self>) {
        self.0.unpark();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.0.unpark();
    }
}

fn drive_stage(stage: Arc<Stage>, name: StageName, cancel: Cancel, slot: Arc<Slot<Outcome>>) {
    let waker = Waker::from(Arc::new(ThreadWaker(thread::current())));
    let mut cx = Context::from_waker(&waker);
    let mut future = Box::pin(stage.run(name));
    loop {
        if cancel.is_set() {
            return;
        }
        match future.as_mut().poll(&mut cx) {
            Poll::Ready(Ok(artifact)) => {
                slot.set(Ok(artifact));
                return;
            }
            Poll::Ready(Err(_)) => {
                slot.set(Err(()));
                return;
            }
            Poll::Pending => thread::park(),
        }
    }
}

// ---------------------------------------------------------------------------
// Waiting
// ---------------------------------------------------------------------------

async fn await_slot<T>(
    guard: &Abort,
    slot: &Arc<Slot<T>>,
    end: Instant,
) -> Result<T, PipelineError> {
    let timer = guard.timer(end);
    poll_fn(|cx| {
        if let Poll::Ready(value) = slot.take_ready(cx) {
            return Poll::Ready(Ok(value));
        }
        if Instant::now() >= end {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        timer.arm(cx.waker());
        if Instant::now() >= end {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if let Poll::Ready(value) = slot.take_ready(cx) {
            return Poll::Ready(Ok(value));
        }
        Poll::Pending
    })
    .await
}

async fn await_stage(
    guard: &Abort,
    stage: &Arc<Stage>,
    name: StageName,
    end: Instant,
) -> Result<Outcome, PipelineError> {
    let slot = guard.spawn_stage(Arc::clone(stage), name);
    await_slot(guard, &slot, end).await
}

fn ensure(outcome: Outcome, name: StageName) -> Result<(), PipelineError> {
    match outcome {
        Ok(_) => Ok(()),
        Err(()) => Err(PipelineError::Stage { name }),
    }
}

fn deadline_end(deadline: Duration) -> Instant {
    let start = Instant::now();
    match start.checked_add(deadline) {
        Some(end) => end,
        None => start + Duration::from_secs(31_536_000),
    }
}

// ---------------------------------------------------------------------------
// Pipeline
// ---------------------------------------------------------------------------

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let stage = Arc::new(stage);
    let end = deadline_end(deadline);
    let guard = Abort::new();

    if Instant::now() >= end {
        return Err(PipelineError::Deadline);
    }

    let a = guard.spawn_stage(Arc::clone(&stage), StageName::FetchA);
    let b = guard.spawn_stage(Arc::clone(&stage), StageName::FetchB);

    let fetch_a = await_slot(&guard, &a, end).await?;
    ensure(fetch_a, StageName::FetchA)?;

    let fetch_b = await_slot(&guard, &b, end).await?;
    ensure(fetch_b, StageName::FetchB)?;

    let combined = await_stage(&guard, &stage, StageName::Combine, end).await?;
    ensure(combined, StageName::Combine)?;

    let published = await_stage(&guard, &stage, StageName::Publish, end).await?;
    match published {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(()) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct Signal {
    waker: Mutex<Option<Waker>>,
}

impl Signal {
    fn register(&self, cx: &Context<'_>) {
        let mut slot = self.waker.lock().unwrap_or_else(|poison| poison.into_inner());
        *slot = Some(cx.waker().clone());
    }
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        let slot = self.waker.lock().unwrap_or_else(|poison| poison.into_inner());
        if let Some(waker) = slot.as_ref() {
            waker.wake_by_ref();
        }
    }
}

struct Watch {
    at: Instant,
    signal: Arc<Signal>,
}

impl Watch {
    fn new(at: Instant) -> Self {
        let signal = Arc::new(Signal { waker: Mutex::new(None) });
        let timer_signal = Arc::clone(&signal);
        let wait = at.saturating_duration_since(Instant::now());
        let _ = thread::spawn(move || {
            thread::sleep(wait);
            let slot = timer_signal
                .waker
                .lock()
                .unwrap_or_else(|poison| poison.into_inner());
            if let Some(waker) = slot.as_ref() {
                waker.wake_by_ref();
            }
        });
        Watch { at, signal }
    }

    fn register(&self, cx: &Context<'_>) {
        self.signal.register(cx);
    }

    fn expired(&self) -> bool {
        Instant::now() >= self.at
    }
}

fn poll_slot<F: Future>(slot: &mut Option<Pin<Box<F>>>, cx: &mut Context<'_>) -> Option<F::Output> {
    let mut fut = match slot.take() {
        Some(fut) => fut,
        None => return None,
    };
    let polled = fut.as_mut().poll(cx);
    match polled {
        Poll::Pending => {
            *slot = Some(fut);
            None
        }
        Poll::Ready(out) => Some(out),
    }
}

struct Fan2<FA, FB> {
    watch: Watch,
    a: Option<Pin<Box<FA>>>,
    b: Option<Pin<Box<FB>>>,
    a_done: bool,
    b_done: bool,
}

impl<FA, FB> Fan2<FA, FB>
where
    FA: Future<Output = Result<Artifact, StageError>>,
    FB: Future<Output = Result<Artifact, StageError>>,
{
    fn new(at: Instant, a: FA, b: FB) -> Self {
        Fan2 {
            watch: Watch::new(at),
            a: Some(Box::pin(a)),
            b: Some(Box::pin(b)),
            a_done: false,
            b_done: false,
        }
    }
}

impl<FA, FB> Future for Fan2<FA, FB>
where
    FA: Future<Output = Result<Artifact, StageError>>,
    FB: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(), PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();
        me.watch.register(cx);
        if me.watch.expired() {
            me.a = None;
            me.b = None;
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        let waker = Waker::from(Arc::clone(&me.watch.signal));
        let mut ctx = Context::from_waker(&waker);

        if !me.a_done {
            match poll_slot(&mut me.a, &mut ctx) {
                None => {}
                Some(Ok(_)) => me.a_done = true,
                Some(Err(_)) => {
                    me.a = None;
                    me.b = None;
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: StageName::FetchA,
                    }));
                }
            }
        }

        if !me.b_done {
            match poll_slot(&mut me.b, &mut ctx) {
                None => {}
                Some(Ok(_)) => me.b_done = true,
                Some(Err(_)) => {
                    me.a = None;
                    me.b = None;
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: StageName::FetchB,
                    }));
                }
            }
        }

        if me.a_done && me.b_done {
            Poll::Ready(Ok(()))
        } else {
            Poll::Pending
        }
    }
}

struct Within<F> {
    watch: Watch,
    name: StageName,
    fut: Option<Pin<Box<F>>>,
}

impl<F> Within<F> {
    fn new(at: Instant, name: StageName, fut: F) -> Self {
        Within {
            watch: Watch::new(at),
            name,
            fut: Some(Box::pin(fut)),
        }
    }
}

impl<F> Future for Within<F>
where
    F: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<Artifact, PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();
        me.watch.register(cx);
        if me.watch.expired() {
            me.fut = None;
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        let waker = Waker::from(Arc::clone(&me.watch.signal));
        let mut ctx = Context::from_waker(&waker);
        match poll_slot(&mut me.fut, &mut ctx) {
            None => Poll::Pending,
            Some(Ok(artifact)) => Poll::Ready(Ok(artifact)),
            Some(Err(_)) => {
                me.fut = None;
                let name = me.name.clone();
                Poll::Ready(Err(PipelineError::Stage { name }))
            }
        }
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let at = Instant::now()
        .checked_add(deadline)
        .unwrap_or_else(|| Instant::now() + Duration::from_secs(86_400));

    Fan2::new(
        at,
        stage.run(StageName::FetchA),
        stage.run(StageName::FetchB),
    )
    .await?;

    Within::new(at, StageName::Combine, stage.run(StageName::Combine)).await?;

    let published =
        Within::new(at, StageName::Publish, stage.run(StageName::Publish)).await?;

    Ok(Published::from(published))
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

fn classify(err: FlowError) -> PipelineError {
    if err.is_cancelled() {
        PipelineError::Cancelled
    } else {
        PipelineError::Deadline
    }
}

fn record(slot: &Mutex<Option<StageName>>, name: StageName) {
    if let Ok(mut guard) = slot.lock() {
        if guard.is_none() {
            *guard = Some(name);
        }
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let scope = Scope::root(Tenant::new("pipeline").expect("`pipeline` is a valid tenant name"));
    let fetch = scope.enter("fetch").map_err(classify)?;

    let failed: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));
    let fetch_note = Arc::clone(&failed);
    let combine_note = Arc::clone(&failed);
    let publish_note = Arc::clone(&failed);

    let outcome: Result<Published, FlowError> =
        within(&scope, "run", deadline, async move {
            let fetcher = stage.clone();
            let combiner = stage.clone();
            let publisher = stage;

            each(
                &fetch,
                "branch",
                NonZeroUsize::new(2),
                [StageName::FetchA, StageName::FetchB],
                move |_branch, name| {
                    let stage = fetcher.clone();
                    let note = Arc::clone(&fetch_note);
                    async move {
                        match stage.run(name.clone()).await {
                            Ok(artifact) => Ok(artifact),
                            Err(_) => {
                                record(&note, name);
                                Err(FlowError::failed("stage failed"))
                            }
                        }
                    }
                },
            )
            .await?;

            let _combined = combiner.run(StageName::Combine).await.map_err(|_| {
                record(&combine_note, StageName::Combine);
                FlowError::failed("stage failed")
            })?;

            let published = publisher.run(StageName::Publish).await.map_err(|_| {
                record(&publish_note, StageName::Publish);
                FlowError::failed("stage failed")
            })?;

            Ok(Published::from(published))
        })
        .await;

    match outcome {
        Ok(published) => Ok(published),
        Err(err) => {
            let seen = failed.lock().ok().and_then(|guard| guard.clone());
            match seen {
                Some(name) => Err(PipelineError::Stage { name }),
                None => Err(classify(err)),
            }
        }
    }
}

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::{timeout, Instant};

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match timeout(deadline, aggregate(ids, fetch, deadline)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn aggregate(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    let total = ids.len();
    let mut pending = ids.into_iter();
    let mut started: usize = 0;
    let start = Instant::now();
    let mut set = JoinSet::<(u32, Result<u64, ()>)>::new();
    let mut sum: u64 = 0;

    loop {
        if started == total && set.is_empty() {
            return Ok(sum);
        }
        if start.elapsed() >= deadline {
            set.abort_all();
            return Err(SolveError::Deadline);
        }

        while set.len() < MAX_IN_FLIGHT && started < total {
            let id = match pending.next() {
                Some(id) => id,
                None => break,
            };
            started += 1;
            let f = fetch.clone();
            set.spawn(async move {
                let value = f.fetch(id).await.map_err(|_| ());
                (id, value)
            });
        }

        if set.is_empty() {
            continue;
        }

        let remaining = deadline.checked_sub(start.elapsed()).unwrap_or_default();
        match timeout(remaining, set.join_next()).await {
            Ok(Some(Ok((_, Ok(value))))) => sum = sum.saturating_add(value),
            Ok(Some(Ok((id, Err(_))))) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Ok(Some(Err(_))) => {}
            Ok(None) => {}
            Err(_) => {
                set.abort_all();
                return Err(SolveError::Deadline);
            }
        }
    }
}

//! Bounded-concurrency aggregation of `Fetcher` results.

use std::collections::VecDeque;
use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

/// Maximum number of `fetch` calls allowed to be in flight at any moment.
const MAX_IN_FLIGHT: usize = 4;

type FetchResult = Result<u64, ai_task_support::FetchError>;

#[derive(Debug)]
#[allow(dead_code)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// Waker handed to a single in-flight fetch. It records that the child needs to
/// be polled again and forwards a single wake to the parent (the task driving
/// `solve`). Taking the parent waker on wake breaks the ownership cycle so a
/// dropped `solve` future releases everything it owns.
struct ChildWaker {
    dirty: AtomicBool,
    parent: Mutex<Option<Waker>>,
}

impl ChildWaker {
    fn new() -> ChildWaker {
        ChildWaker {
            dirty: AtomicBool::new(true),
            parent: Mutex::new(None),
        }
    }

    fn lock_parent(&self) -> std::sync::MutexGuard<'_, Option<Waker>> {
        self.parent.lock().unwrap_or_else(|e| e.into_inner())
    }

    fn set_parent(&self, waker: &Waker) {
        let mut slot = self.lock_parent();
        match slot.as_ref() {
            Some(existing) if existing.will_wake(waker) => {}
            _ => *slot = Some(waker.clone()),
        }
    }

    fn take_dirty(&self) -> bool {
        self.dirty.swap(false, Ordering::AcqRel)
    }

    fn notify(&self) {
        self.dirty.store(true, Ordering::Release);
        let parent = self.lock_parent().take();
        if let Some(parent) = parent {
            parent.wake();
        }
    }
}

impl Wake for ChildWaker {
    fn wake(self: Arc<Self>) {
        self.notify();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.notify();
    }
}

/// One in-flight fetch plus the machinery needed to poll it from the parent.
struct Task {
    id: u32,
    child: Arc<ChildWaker>,
    waker: Waker,
    fut: Option<Pin<Box<dyn Future<Output = FetchResult>>>>,
    result: Option<FetchResult>,
}

impl Task {
    fn new(id: u32, fetch: &Fetcher) -> Task {
        let child = Arc::new(ChildWaker::new());
        let waker = Waker::from(child.clone());
        let f = fetch.clone();
        Task {
            id,
            child,
            waker,
            fut: Some(Box::pin(async move { f.fetch(id).await })),
            result: None,
        }
    }

    fn is_done(&self) -> bool {
        self.result.is_some()
    }

    fn value(mut self) -> FetchResult {
        self.result.take().expect("task completed")
    }

    fn poll(&mut self, cx: &Context<'_>) {
        if self.result.is_some() {
            return;
        }
        self.child.set_parent(cx.waker());
        if !self.child.take_dirty() {
            return;
        }
        let waker = self.waker.clone();
        let mut child_cx = Context::from_waker(&waker);
        let polled = match self.fut.as_mut() {
            Some(fut) => fut.as_mut().poll(&mut child_cx),
            None => return,
        };
        if let Poll::Ready(result) = polled {
            self.fut = None;
            self.result = Some(result);
        }
    }
}

/// Wakes the parent once `budget` has elapsed. The thread parks on a condvar
/// with a bounded wait so it also notices an early finish, and the guard's
/// `Drop` (run when `solve` completes or is dropped) releases it promptly.
struct Timer {
    flag: Arc<TimerFlag>,
}

struct TimerFlag {
    done: Mutex<bool>,
    cv: Condvar,
}

impl Timer {
    fn spawn(parent: &Waker, budget: Duration) -> Timer {
        let flag = Arc::new(TimerFlag {
            done: Mutex::new(false),
            cv: Condvar::new(),
        });
        let thread_flag = flag.clone();
        let waker = parent.clone();
        let spawned = std::thread::Builder::new()
            .name("aggregate-deadline".to_string())
            .spawn(move || {
                let start = Instant::now();
                loop {
                    let guard = thread_flag
                        .done
                        .lock()
                        .unwrap_or_else(|e| e.into_inner());
                    if *guard {
                        return;
                    }
                    let elapsed = start.elapsed();
                    if elapsed >= budget {
                        drop(guard);
                        waker.wake();
                        return;
                    }
                    let wait = (budget - elapsed).min(Duration::from_secs(60));
                    let (guard, _) = thread_flag
                        .cv
                        .wait_timeout(guard, wait)
                        .unwrap_or_else(|e| e.into_inner());
                    if *guard {
                        return;
                    }
                    drop(guard);
                }
            });
        if spawned.is_err() {
            // Without the timer the deadline is still enforced on the next
            // poll of `solve`; there simply is no forced wake-up.
        }
        Timer { flag }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        let mut done = self.flag.done.lock().unwrap_or_else(|e| e.into_inner());
        *done = true;
        self.flag.cv.notify_all();
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let mut pending: VecDeque<u32> = ids.into();
    let mut tasks: Vec<Task> = Vec::new();
    let mut sum: u64 = 0;
    let start = Instant::now();
    let mut timer: Option<Timer> = None;

    let outcome = poll_fn(|cx| -> Poll<Result<u64, SolveError>> {
        if start.elapsed() >= deadline {
            return Poll::Ready(Err(SolveError::Deadline));
        }
        if timer.is_none() {
            timer = Some(Timer::spawn(cx.waker(), deadline));
        }
        loop {
            if start.elapsed() >= deadline {
                return Poll::Ready(Err(SolveError::Deadline));
            }

            while tasks.len() < MAX_IN_FLIGHT {
                match pending.pop_front() {
                    Some(id) => tasks.push(Task::new(id, &fetch)),
                    None => break,
                }
            }

            for task in tasks.iter_mut() {
                task.poll(cx);
            }

            let mut collected = false;
            let mut index = 0;
            while index < tasks.len() {
                if !tasks[index].is_done() {
                    index += 1;
                    continue;
                }
                let task = tasks.remove(index);
                collected = true;
                let id = task.id;
                match task.value() {
                    Ok(value) => sum += value,
                    Err(_) => return Poll::Ready(Err(SolveError::Fetch { id })),
                }
            }

            if tasks.is_empty() && pending.is_empty() {
                return Poll::Ready(Ok(sum));
            }
            if !collected {
                return Poll::Pending;
            }
        }
    })
    .await;

    drop(timer);
    outcome
}

use std::collections::VecDeque;
use std::time::Duration;

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

/// Maximum number of `fetch` calls allowed to be in flight at once.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    #[allow(dead_code)]
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    match timeout(deadline, drive(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

/// Runs every queued fetch with a hard in-flight bound, stopping as soon as a
/// failure is observed. The `JoinSet` owns everything it started, so dropping
/// this future (cancellation, deadline, caller drop) aborts the live fetches.
async fn drive(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut queue: VecDeque<u32> = ids.into_iter().collect();
    let mut set: JoinSet<(u32, Result<u64, ai_task_support::FetchError>)> = JoinSet::new();

    let mut sum: u64 = 0;
    let mut failed: Option<u32> = None;

    while failed.is_none() {
        // Top up to the concurrency bound, never beyond it.
        while set.len() < MAX_IN_FLIGHT {
            let Some(id) = queue.pop_front() else { break };
            let task_fetch = fetch.clone();
            set.spawn(async move { (id, task_fetch.fetch(id).await) });
        }

        match set.join_next().await {
            None => break,
            Some(Ok((_, Ok(value)))) => sum = sum.wrapping_add(value),
            Some(Ok((id, Err(_)))) => {
                // Stop feeding the queue: no further fetch is started.
                failed = Some(id);
            }
            Some(Err(_)) => {
                // A task ended abnormally; keep draining, never refill past it.
            }
        }
    }

    match failed {
        Some(id) => Err(SolveError::Fetch { id }),
        None => Ok(sum),
    }
}

//! A bounded four-stage pipeline over a caller-supplied [`Stage`].
//!
//! `fetch_a` and `fetch_b` are independent and are in flight at the same time;
//! `combine` requires both of them, and `publish` requires `combine`.
//!
//! The three contract guarantees fall out of two design decisions:
//!
//! * **Nothing is spawned.** Every stage future is a field of the state that
//!   `solve` itself owns, so dropping the returned future drops the in-flight
//!   stages with it — there is no detached work left behind. This is also why
//!   the concurrency is expressed by polling both fetch futures from one
//!   `poll` call rather than by handing them to a task set: `Stage::run`
//!   returns an opaque future with no `Send` bound, so it cannot be spawned.
//! * **Every stage is raced against one absolute deadline instant.** A stage
//!   that loses the race has its future dropped at that moment, so it cannot
//!   outlive the deadline, and because the instant is absolute the budget
//!   applies to the pipeline as a whole rather than restarting per stage.

use std::future::Future;
use std::mem;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::time::{sleep_until, Instant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type BoxFut<'a, T> = Pin<Box<dyn Future<Output = T> + 'a>>;

/// A single stage polled alongside the deadline.
///
/// The stage future and the timer are fields of the same object, so when the
/// timer wins the stage future is dropped with it and stops immediately.
struct Raced<'a> {
    name: StageName,
    /// `None` means the stage reported an error; the error payload itself is
    /// not something the pipeline contract lets us inspect.
    stage: BoxFut<'a, Option<Artifact>>,
    timer: BoxFut<'a, ()>,
    done: bool,
}

impl<'a> Raced<'a> {
    fn new(stage: &'a Stage, name: StageName, deadline_at: Instant) -> Self {
        Raced {
            name,
            stage: Box::pin(async move { stage.run(name).await.ok() }),
            timer: Box::pin(sleep_until(deadline_at)),
            done: false,
        }
    }
}

impl<'a> Future for Raced<'a> {
    type Output = Result<Artifact, PipelineError>;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.as_mut().get_mut();
        if this.done {
            return Poll::Pending;
        }
        if let Poll::Ready(outcome) = this.stage.as_mut().poll(cx) {
            this.done = true;
            return Poll::Ready(outcome.ok_or(PipelineError::Stage { name: this.name }));
        }
        if this.timer.as_mut().poll(cx).is_ready() {
            this.done = true;
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        Poll::Pending
    }
}

enum Slot {
    Pending,
    Done(Option<Artifact>),
}

/// The two independent fetches, driven as a single future.
///
/// Both are polled on every wake, so they are genuinely concurrent, and
/// whichever finishes first is not preferred over the other. The pair
/// completes as soon as either fetch fails, which drops the sibling mid-flight
/// and keeps `combine` and `publish` from ever being constructed.
struct Fetches<'a> {
    a: BoxFut<'a, Option<Artifact>>,
    b: BoxFut<'a, Option<Artifact>>,
    timer: BoxFut<'a, ()>,
    a_slot: Slot,
    b_slot: Slot,
    done: bool,
}

impl<'a> Fetches<'a> {
    fn new(stage: &'a Stage, deadline_at: Instant) -> Self {
        Fetches {
            a: Box::pin(async move { stage.run(StageName::FetchA).await.ok() }),
            b: Box::pin(async move { stage.run(StageName::FetchB).await.ok() }),
            timer: Box::pin(sleep_until(deadline_at)),
            a_slot: Slot::Pending,
            b_slot: Slot::Pending,
            done: false,
        }
    }
}

impl<'a> Future for Fetches<'a> {
    type Output = Result<(Artifact, Artifact), PipelineError>;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.as_mut().get_mut();
        if this.done {
            return Poll::Pending;
        }

        if let Slot::Pending = this.a_slot {
            if let Poll::Ready(outcome) = this.a.as_mut().poll(cx) {
                this.a_slot = Slot::Done(outcome);
            }
        }
        if let Slot::Pending = this.b_slot {
            if let Poll::Ready(outcome) = this.b.as_mut().poll(cx) {
                this.b_slot = Slot::Done(outcome);
            }
        }

        // A fetch failure outranks the deadline: it is the more specific
        // answer, and it is what forbids every later stage.
        let failed = match (&this.a_slot, &this.b_slot) {
            (Slot::Done(None), _) => Some(StageName::FetchA),
            (_, Slot::Done(None)) => Some(StageName::FetchB),
            _ => None,
        };
        if let Some(name) = failed {
            this.done = true;
            return Poll::Ready(Err(PipelineError::Stage { name }));
        }

        if this.timer.as_mut().poll(cx).is_ready() {
            this.done = true;
            return Poll::Ready(Err(PipelineError::Deadline));
        }

        if let (Slot::Done(Some(_)), Slot::Done(Some(_))) = (&this.a_slot, &this.b_slot) {
            // Move the artifacts out rather than cloning them; the `Artifact`
            // contract only promises `value()`, not `Clone`. The `None` arms
            // are unreachable here: a `Done(None)` slot already returned
            // above.
            let a = match mem::replace(&mut this.a_slot, Slot::Pending) {
                Slot::Done(Some(value)) => value,
                _ => return Poll::Pending,
            };
            let b = match mem::replace(&mut this.b_slot, Slot::Pending) {
                Slot::Done(Some(value)) => value,
                _ => return Poll::Pending,
            };
            this.done = true;
            return Poll::Ready(Ok((a, b)));
        }

        Poll::Pending
    }
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    // Taken on first poll, so the budget covers the pipeline end to end.
    let deadline_at = Instant::now() + deadline;

    // Both fetches run concurrently and must both succeed before anything
    // downstream is even created.
    let (_a, _b) = Fetches::new(&stage, deadline_at).await?;

    // Each remaining stage is bounded by the same absolute instant, so no stage
    // can restart the clock.
    let _combined = Raced::new(&stage, StageName::Combine, deadline_at).await?;
    let published = Raced::new(&stage, StageName::Publish, deadline_at).await?;

    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

type BoxedFetch = Pin<Box<dyn Future<Output = Fetch> + Send + 'static>>;

enum Fetch {
    A(Result<Artifact, StageErrorName>),
    B(Result<Artifact, StageErrorName>),
}

struct StageErrorName;

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let fetches: Vec<BoxedFetch> = vec![
        Box::pin(fetch_a(stage.clone())),
        Box::pin(fetch_b(stage.clone())),
    ];

    let fetched = join_all_bounded(2, fetches).await;

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;
    for outcome in fetched {
        match outcome {
            Fetch::A(Ok(artifact)) => a = Some(artifact),
            Fetch::B(Ok(artifact)) => b = Some(artifact),
            Fetch::A(Err(_)) => return Err(PipelineError::Stage { name: StageName::FetchA }),
            Fetch::B(Err(_)) => return Err(PipelineError::Stage { name: StageName::FetchB }),
        }
    }

    let (_a, _b) = match (a, b) {
        (Some(a), Some(b)) => (a, b),
        _ => return Err(PipelineError::Cancelled),
    };

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

async fn fetch_a(stage: Stage) -> Fetch {
    match stage.run(StageName::FetchA).await {
        Ok(artifact) => Fetch::A(Ok(artifact)),
        Err(_) => Fetch::A(Err(StageErrorName)),
    }
}

async fn fetch_b(stage: Stage) -> Fetch {
    match stage.run(StageName::FetchB).await {
        Ok(artifact) => Fetch::B(Ok(artifact)),
        Err(_) => Fetch::B(Err(StageErrorName)),
    }
}

//! A small four-stage pipeline: `fetch_a` and `fetch_b` run concurrently,
//! then `combine`, then `publish`.
//!
//! Ownership rules give us the cancellation guarantees for free: the fetch
//! work lives in a `JoinSet`, which aborts everything it still owns when it is
//! dropped. Dropping the `solve` future — by the caller, or by `timeout` when
//! the deadline elapses — drops that set, so no stage outlives `solve`.

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let mut fetches = JoinSet::new();
    for name in [StageName::FetchA, StageName::FetchB] {
        let stage = stage.clone();
        fetches.spawn(async move { (name, stage.run(name).await) });
    }

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;
    while a.is_none() || b.is_none() {
        match fetches.join_next().await {
            Some(Ok((StageName::FetchA, Ok(artifact)))) => a = Some(artifact),
            Some(Ok((StageName::FetchB, Ok(artifact)))) => b = Some(artifact),
            Some(Ok((name, Err(_)))) => {
                // Dropping `fetches` aborts the sibling fetch; nothing later runs.
                drop(fetches);
                return Err(PipelineError::Stage { name });
            }
            Some(Ok((_, Ok(_)))) | Some(Err(_)) | None => {
                drop(fetches);
                return Err(PipelineError::Cancelled);
            }
        }
    }

    // `combine` requires both fetches to have succeeded; they are now both held.
    let _ = (a, b);

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(published.into())
}
